class BankAccount {
    private int balance = 1000;

    // Race condition: two threads can read 1000 simultaneously
    public void withdraw(int amount) {
        if (balance >= amount) {  // Thread A and B both see 1000
            balance -= amount;    // Both subtract — balance goes negative!
        }
    }

    // Fixed:
    public synchronized void withdrawSafe(int amount) {
        if (balance >= amount) { balance -= amount; }
    }
}
